{"results": [{"id": "hp_doc_4901baaddb6553340274b24b85003c016b20518d9c5b7e0b1515d203d2d7734c", "title": "Live at Winterland '68", "text": "Live at Winterland '68 is an album by Janis Joplin with her band Big Brother and The Holding Company. It was recorded at the Winterland Ballroom on April 12, 1968, and April 13, 1968 and includes live renditions of songs from their studio albums.", "score": 28.8671}, {"id": "hp_doc_ada3154d44d8287ca97efe74b19eeb03d0de18704c3477b31e690bb9653e17f6", "title": "Live at Winterland '76", "text": "Live at Winterland '76 is a live album by the Electric Light Orchestra (ELO) released in 1998.", "score": 19.5498}, {"id": "hp_doc_7e53522b0aceef66e7b5ca08328a8212809fb80af798257adc7ae33fe044b6ff", "title": "Winterland June 1977: The Complete Recordings", "text": "Winterland June 1977: The Complete Recordings is a 9 CD live album by the American rock band the Grateful Dead. It contains three complete concerts. It was recorded on June 7, 8, and 9, 1977, at the Winterland Ballroom in San Francisco, California. The album was released on October 1, 2009.", "score": 16.1106}], "remaining_searches": 2}
